{% comment %} --- KONFIGURACJA DUETU --- {% endcomment %}
{% assign current_variant_id = product.selected_or_first_available_variant.id %}
{% assign mist_variant_id = 10088600699213 %} 
{% assign mist_image_url = 'https://routines.pl/cdn/shop/files/EAN5906233401766.jpg?v=1749476554&width=300' %}

<div class="duo-bundle-section">
  <h3 class="duo-title">Kup w duecie</h3>

  <div class="duo-flex-container">
    <div class="duo-visual-part">
      <div class="duo-img-wrapper">
        <img src="{{ product.featured_image | img_url: '300x' }}" alt="{{ product.title }}">
      </div>
      <div class="duo-plus-icon">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
      </div>
      <div class="duo-img-wrapper">
        <img src="{{ mist_image_url }}" alt="Mgiełka GLOW">
      </div>
    </div>

    <div class="duo-info-part">
      <p class="duo-names">
        <strong>Ten produkt</strong> + Nawilżająca mgiełka GLOW z witaminą B12
      </p>
      <div class="duo-price-box">
        <span class="duo-price-label">Cena mgiełki w duecie:</span>
        <div class="duo-price-values">
          <span class="duo-old-price">29,99 zł</span>
          <span class="duo-new-price">14,99 zł</span>
        </div>
      </div>
    </div>

    <div class="duo-action-part">
      <button type="button" class="duo-submit-btn-outline" onclick="addDuoBundle({{ current_variant_id }}, {{ mist_variant_id }}, this)">
        <span class="btn-text">dodaj duet do koszyka</span>
        <div class="btn-loader-black"></div>
      </button>
    </div>
  </div>
</div>

<style>
  .duo-bundle-section {
    margin: 30px 0; padding: 24px; background: #ffffff; border: 1px solid #eeeeee; border-radius: 12px; font-family: 'Poppins', sans-serif;
  }
  .duo-title { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px; margin: 0 0 20px 0; color: #000; }
  .duo-flex-container { display: flex; align-items: center; gap: 30px; }
  .duo-visual-part { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
  .duo-img-wrapper { width: 80px; height: 80px; border-radius: 8px; background: #f9f9f9; padding: 4px; display: flex; align-items: center; justify-content: center; border: 1px solid #f0f0f0; }
  .duo-img-wrapper img { max-width: 100%; max-height: 100%; object-fit: contain; }
  .duo-info-part { flex-grow: 1; }
  .duo-names { font-size: 14px; line-height: 1.4; color: #333; margin: 0 0 8px 0; }
  .duo-price-label { display: block; font-size: 10px; color: #999; text-transform: uppercase; font-weight: 600; margin-bottom: 2px; }
  .duo-price-values { display: flex; align-items: baseline; gap: 8px; }
  .duo-old-price { font-size: 12px; color: #bbbbbb; text-decoration: line-through; }
  .duo-new-price { font-size: 19px; color: #d10000; font-weight: 800; }

  .duo-submit-btn-outline {
    background: #ffffff; color: #000; border: 1.5px solid #000; padding: 12px 24px; border-radius: 50px;
    font-size: 13px; font-weight: 700; cursor: pointer; transition: all 0.25s ease; white-space: nowrap;
    position: relative; min-width: 220px; text-transform: lowercase;
  }
  .duo-submit-btn-outline:hover { background: #f8f8f8; }
  .duo-submit-btn-outline.loading .btn-text { visibility: hidden; }
  .btn-loader-black {
    display: none; width: 18px; height: 18px; border: 2px solid rgba(0,0,0,0.1); border-top-color: #000;
    border-radius: 50%; position: absolute; top: 50%; left: 50%; margin: -9px 0 0 -9px;
    animation: duo-spin 0.8s linear infinite;
  }
  .duo-submit-btn-outline.loading .btn-loader-black { display: block; }
  @keyframes duo-spin { to { transform: rotate(360deg); } }

  @media (max-width: 990px) {
    .duo-flex-container { flex-direction: column; align-items: flex-start; gap: 20px; }
    .duo-action-part, .duo-submit-btn-outline { width: 100%; }
  }
</style>

<script>
async function addDuoBundle(id1, id2, btn) {
  if (btn.classList.contains('loading')) return;
  btn.classList.add('loading');

  // Przygotowanie danych w formacie FormData (bardzo stabilny format)
  let formData = new FormData();
  formData.append('items[0][id]', id1);
  formData.append('items[0][quantity]', 1);
  formData.append('items[1][id]', id2);
  formData.append('items[1][quantity]', 1);

  try {
    const response = await fetch('/cart/add.js', {
      method: 'POST',
      body: formData
    });

    const data = await response.json();

    if (response.ok) {
      btn.classList.remove('loading');
      btn.style.borderColor = '#28a745';
      btn.style.color = '#28a745';
      btn.innerHTML = 'dodano! odświeżam...';

      // WYMUSZONE ODŚWIEŻENIE STRONY
      // To najpewniejszy sposób, by produkty pojawiły się w koszyku w każdym motywie
      window.location.reload(); 
    } else {
      throw new Error(data.description || 'Błąd Shopify');
    }
  } catch (error) {
    console.error('Szczegóły błędu:', error);
    btn.classList.remove('loading');
    btn.innerHTML = 'brak wariantu lub zapasów';

    setTimeout(() => {
      btn.innerHTML = '<span class="btn-text">dodaj duet do koszyka</span><div class="btn-loader-black"></div>';
    }, 4000);
  }
}
</script>
